import { type SynapseEnhancedHttpClient } from "../utils/http.ts";
import { ErrorCode } from "../utils/error-codes.ts";
import { mapParams } from "../utils/api-mapping.ts";
import { SynapseAdminApi } from "../constants/api.ts";
import { handleApiResponse } from "../utils/response-formatter.ts";
import { BaseApi } from "../utils/base-api.ts";

export interface ISecurityEvent {
    event_id: string;
    event_type: string;
    severity: "low" | "medium" | "high" | "critical";
    user_id?: string;
    room_id?: string;
    description: string;
    metadata?: Record<string, unknown>;
    created_at: string;
    resolved_at?: string;
    resolved_by?: string;
}

export interface ISecurityEventParams {
    user_id?: string;
    event_type?: string;
    severity?: string;
    limit?: number;
    offset?: number;
    resolved?: boolean;
}

export interface ISecurityStats {
    total_events: number;
    events_by_severity: {
        low: number;
        medium: number;
        high: number;
        critical: number;
    };
    events_by_type: Record<string, number>;
    recent_events_count: number;
    resolved_events_count: number;
    unresolved_events_count: number;
    average_resolution_time_hours?: number;
    top_event_types: { type: string; count: number }[];
    events_trend: { date: string; count: number }[];
}

export interface ISecurityAdminApi {
    getEvents(params?: ISecurityEventParams): Promise<ISecurityEvent[]>;
    getEvent(eventId: string): Promise<ISecurityEvent | null>;
    resolveEvent(eventId: string, resolution: string): Promise<boolean>;
    getStats(): Promise<ISecurityStats>;
    getEventsByUser(userId: string, limit?: number): Promise<ISecurityEvent[]>;
    getEventsByRoom(roomId: string, limit?: number): Promise<ISecurityEvent[]>;
    getUnresolvedEvents(limit?: number): Promise<ISecurityEvent[]>;
    getEventsBySeverity(severity: string, limit?: number): Promise<ISecurityEvent[]>;
}

export class SecurityAdminApi extends BaseApi implements ISecurityAdminApi {
    public constructor(httpClient: SynapseEnhancedHttpClient) {
        super(httpClient);
    }

    /**
     * Get security events with optional filtering
     */
    public async getEvents(params?: ISecurityEventParams): Promise<ISecurityEvent[]> {
        const queryParams: Record<string, unknown> = {};

        if (params?.user_id) {
            queryParams.user_id = params.user_id;
        }
        if (params?.event_type) {
            queryParams.event_type = params.event_type;
        }
        if (params?.severity) {
            queryParams.severity = params.severity;
        }
        if (params?.limit !== undefined) {
            queryParams.limit = params.limit;
        }
        if (params?.offset !== undefined) {
            queryParams.offset = params.offset;
        }
        if (params?.resolved !== undefined) {
            queryParams.resolved = params.resolved;
        }

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                events?: ISecurityEvent[];
            };
            error?: string;
        }>(SynapseAdminApi.SECURITY_ADMIN_EVENTS, queryParams);

        const data = handleApiResponse(response, "Failed to get security events");
        return data.events || [];
    }

    /**
     * Get a specific security event by ID
     */
    public async getEvent(eventId: string): Promise<ISecurityEvent | null> {
        if (!eventId || typeof eventId !== "string" || eventId.trim().length === 0) {
            throw this.createError("eventId is required and must be a non-empty string", ErrorCode.INVALID_PARAM);
        }

        try {
            const response = await this.httpClient.get<{
                status: string;
                data?: {
                    event?: ISecurityEvent;
                };
                error?: string;
            }>(`${SynapseAdminApi.SECURITY_ADMIN_EVENTS}/${encodeURIComponent(eventId)}`);

            const data = handleApiResponse(response, "Failed to get security event");
            return data.event || null;
        } catch (error) {
            if (error instanceof Error && (error.message.includes("404") || error.message.includes("failed"))) {
                return null;
            }
            throw error;
        }
    }

    /**
     * Resolve a security event
     */
    public async resolveEvent(eventId: string, resolution: string): Promise<boolean> {
        const mappedParams = mapParams({ eventId, resolution }, "securityAdmin");
        const response = await this.httpClient.post<{
            status: string;
            error?: string;
        }>(`${SynapseAdminApi.SECURITY_ADMIN_EVENTS}/${encodeURIComponent(eventId)}/resolve`, mappedParams);

        handleApiResponse(response, "Failed to resolve security event");
        return true;
    }

    /**
     * Get security statistics
     */
    public async getStats(): Promise<ISecurityStats> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                stats?: ISecurityStats;
            };
            error?: string;
        }>(`${SynapseAdminApi.SECURITY_ADMIN}/stats`);

        const data = handleApiResponse(response, "Failed to get security stats");
        return data.stats!;
    }

    /**
     * Get events for a specific user
     */
    public async getEventsByUser(userId: string, limit: number = 50): Promise<ISecurityEvent[]> {
        return this.getEvents({ user_id: userId, limit: limit });
    }

    /**
     * Get events for a specific room
     */
    public async getEventsByRoom(roomId: string, limit: number = 50): Promise<ISecurityEvent[]> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                events?: ISecurityEvent[];
            };
            error?: string;
        }>(SynapseAdminApi.SECURITY_ADMIN_EVENTS, {
            room_id: roomId,
            limit: limit,
        });

        const data = handleApiResponse(response, "Failed to get room security events");
        return data.events || [];
    }

    /**
     * Get all unresolved events
     */
    public async getUnresolvedEvents(limit: number = 50): Promise<ISecurityEvent[]> {
        return this.getEvents({ resolved: false, limit: limit });
    }

    /**
     * Get events by severity level
     */
    public async getEventsBySeverity(
        severity: "low" | "medium" | "high" | "critical",
        limit: number = 50,
    ): Promise<ISecurityEvent[]> {
        return this.getEvents({ severity: severity, limit: limit });
    }

    /**
     * Get critical events that need immediate attention
     */
    public async getCriticalEvents(limit: number = 20): Promise<ISecurityEvent[]> {
        return this.getEventsBySeverity("critical", limit);
    }

    /**
     * Get event count by type
     */
    public async getEventCountByType(): Promise<Record<string, number>> {
        const stats = await this.getStats();
        return stats.events_by_type;
    }

    /**
     * Check if there are any unresolved critical events
     */
    public async hasCriticalEvents(): Promise<boolean> {
        const criticalEvents = await this.getCriticalEvents(1);
        return criticalEvents.length > 0;
    }
}
